        D = line_row - r

        if D == 2:
            # toward + perps + right diagonal (maybe left diagonal clipped at edge?)
            diag_r = line_row - D - 1  # = 0
            if 0 <= r+1 < 12:
                outputs.add((r+1, c))
            if 0 <= c-1 < 8:
