            if 0 <= c+1 < 8:
                outputs.add((r, c+1))
            # Only right diag since left is clipped
            if 0 <= c+2 < 8:
                outputs.add((diag_r, c+2))

        elif D == 3:
            # toward + perps
            if 0 <= r+1 < 12:
                outputs.add((r+1, c))
            if 0 <= c-1 < 8:
